const http = require('http');
const crypto = require('crypto');

const PORT = Number(process.env.PORT) || 3000;
const users = new Map();

function json(response, status, data) {
  response.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Access-Control-Allow-Origin': '*'
  });
  response.end(JSON.stringify(data));
}

function requestBody(request) {
  return new Promise((resolve, reject) => {
    let body = '';
    request.setEncoding('utf8');
    request.on('data', chunk => {
      body += chunk;
      if (body.length > 1024 * 1024) {
        reject(new Error('Request body is too large'));
        request.destroy();
      }
    });
    request.on('end', () => {
      if (!body) return resolve({});
      try { resolve(JSON.parse(body)); }
      catch { reject(new Error('Invalid JSON')); }
    });
    request.on('error', reject);
  });
}

function id() {
  return crypto.randomBytes(12).toString('hex');
}

function safeUser(user) {
  const { password, ...publicUser } = user;
  return publicUser;
}

async function handle(request, response) {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  const { method } = request;

  if (method === 'OPTIONS') {
    response.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type'
    });
    return response.end();
  }

  if (method === 'GET' && url.pathname === '/health') {
    return json(response, 200, { status: 'ok', uptime: process.uptime(), timestamp: new Date().toISOString() });
  }

  if (method === 'GET' && url.pathname === '/users') {
    return json(response, 200, { users: [...users.values()].map(safeUser), count: users.size });
  }

  if (method === 'POST' && url.pathname === '/users') {
    const data = await requestBody(request);
    const name = String(data.name || '').trim();
    const email = String(data.email || '').trim().toLowerCase();
    const password = String(data.password || '');
    if (!name || !email || password.length < 8) {
      return json(response, 400, { error: 'name, email, and a password of at least 8 characters are required' });
    }
    if ([...users.values()].some(user => user.email === email)) {
      return json(response, 409, { error: 'Email already exists' });
    }
    const user = { id: id(), name, email, password, createdAt: new Date().toISOString() };
    users.set(user.id, user);
    return json(response, 201, safeUser(user));
  }

  if (method === 'DELETE' && url.pathname.startsWith('/users/')) {
    const userId = url.pathname.slice('/users/'.length);
    if (!users.delete(userId)) return json(response, 404, { error: 'User not found' });
    return json(response, 200, { message: 'User deleted' });
  }

  return json(response, 404, { error: 'Route not found' });
}

const server = http.createServer((request, response) => {
  handle(request, response).catch(error => {
    console.error(error);
    json(response, 500, { error: 'Internal server error' });
  });
});

server.listen(PORT, () => {
  console.log(`API listening on http://localhost:${PORT}`);
});
